function [y] = deriv_dke_yp(x,n)%%	Numerical determination of the n-th order derivative (n<=3). %	WARNING: the result must be divided by (dx)^n to have d^nx/dx^n%%	Input:%	%		- x: initial vector [m,1]%		- n: order of the derivative [1,1]%		  (default = 1)%%	Output:%%		- y: d^nx [m,1]%%by Y.PEYSSON CEA-DRFC 14/04/1993 <yves.peysson@cea.fr>%revised for MatLab 4.1 (07/09/1994) %revised for MatLab 5.2 (31/08/2000) %%if nargin < 1,	info_dke_yp(2,'Wrong number of input arguments for deriv_dke_yp');	return;endif nargin == 1,	n = 1;end%[n1,n2] = size(x);if (n1 ~= 1) & (n2 ~=1),	error('x must be a vector');endif (n < 0) | (n > 3),	error('0 <= n <= 3');end%x = x(:);n1 = length(x);n2 = 1;%if n == 0,	y = x;elseif n==1, 	bb = 3*x([1,n1],:) - 4*x([2,n1-1],:) + x([3,n1-2],:);    	y = [-bb(1,:);  x(3:n1,:)-x(1:n1-2,:);  bb(2,:)]/2;elseif n==2, 	bb = 2*x([1,n1],:) - 5*x([2,n1-1],:) + 4*x([3,n1-2],:) - x([4,n1-3],:);   		   	 	y = [-bb(1,:);  x(3:n1,:)-2*x(2:n1-1,:)+x(1:n1-2,:);  bb(2,:)];elseif n==3, 	bb =   x([1:2,n1-1:n1],:) - 3*x([2:3,n1-2:n1-1],:) + 3*x([3:4,n1-3:n1-2],:) - x([4:5,n1-4:n1-3],:); 	y = [x(5:n1,:)-2*x(4:n1-1,:)+2*x(2:n1-3,:)-x(1:n1-4,:)]; 	y = [-bb(1:2,:); y/2; bb(3:4,:)]; end	